return ['domain'=>NULL,'plural-forms'=>'nplurals=3; plural=(n % 10 == 1 && n % 100 != 11) ? 0 : ((n % 10 >= 2 && n % 10 <= 4 && (n % 100 < 12 || n % 100 > 14)) ? 1 : 2);','language'=>'sr_RS','project-id-version'=>'Babilim 1.2.1','pot-creation-date'=>'2026-11-09T07:54:37+00:00','po-revision-date'=>'2026-11-09T07:54:37+00:00','x-generator'=>'Babilim','messages'=>['Sent when you press Enable Babilim, and again if the site has to register anew: your site\'s URL, the WordPress, PHP and Babilim versions, the language of your site and the languages in use on it, and a public key generated for this site.'=>'Шаље се када притиснете Омогући Babilim, и поново ако сајт мора да се региструје изнова: URL вашег сајта, верзије Вордпреса, PHP-а и Babilim-а, језик вашег сајта и језици у употреби на њему, као и јавни кључ генерисан за овај сајт.','Sent on every check: the list of installed plugins and themes with the state of any Babilim translation installed for them, the languages in use, and short diagnostic codes.'=>'Шаље се при свакој провери: списак инсталираних додатака и тема са стањем сваког Babilim превода инсталираног за њих, језици у употреби и кратке дијагностичке шифре.','Every request includes your site\'s URL, and the site\'s access token is included whenever the service needs it.'=>'Сваки захтев садржи URL вашег сајта, а приступни токен сајта се додаје кад год је услузи потребан.','What Babilim sends to the service'=>'Шта Babilim шаље услузи','Your site\'s URL'=>'URL вашег сајта','WordPress version'=>'Верзија Вордпреса','PHP version'=>'PHP верзија','Babilim version'=>'Babilim верзија','Your site\'s language'=>'Језик вашег сајта','Languages in use on your site'=>'Језици у употреби на вашем сајту','A public key for this site'=>'Јавни кључ за овај сајт','A public key generated for this site, used to prove requests genuinely come from this site. Only the public half is ever sent; the private half stays on your site.'=>'Јавни кључ генерисан за овај сајт, који служи као доказ да захтеви заиста потичу са овог сајта. Шаље се само јавни део; приватни део остаје на вашем сајту.','Installed plugins and themes'=>'Инсталирани додаци и теме','For every installed plugin and theme: its name (slug), version, text domain, whether it is listed on WordPress.org, and the languages it already includes. For each Babilim translation you have installed: which version it is, when it was last checked, and whether it passed its file check.'=>'За сваки инсталирани додатак и тему: његово име (slug), верзија, text domain, да ли је наведен на WordPress.org и које језике већ укључује. За сваки Babilim превод који сте инсталирали: која је то верзија, када је последњи пут проверен и да ли је прошао проверу датотека.','Source files (only if you confirm an upload)'=>'Изворне датотеке (само ако потврдите отпремање)','Diagnostic codes'=>'Дијагностичке шифре','Up to 20 short diagnostic codes (for example, a translation file that failed its check), each with the plugin or theme, the language and the time it happened. They never contain any text from your site or any translated text.'=>'До 20 кратких дијагностичких шифара (на пример, датотека превода која није прошла проверу), свака са додатком или темом, језиком и временом када се догодило. Никада не садрже никакав текст са вашег сајта нити преведени текст.','%1$d site on this network is set to erase its Babilim identity when the plugin is deleted. The paid license attached to that site could then not be restored automatically; you would have to contact Babilim support at %2$s. To keep the identity, press Cancel, untick "Delete all Babilim data on uninstall" in that site\'s Babilim settings, and deactivate again. Deactivate anyway?'=>'%1$d сајт у овој мрежи је подешен да избрише свој Babilim идентитет када се додатак обрише. Плаћена лиценца везана за тај сајт тада се не би могла аутоматски вратити; морали бисте да контактирате Babilim подршку на %2$s. Да бисте задржали идентитет, притисните Откажи, уклоните ознаку са „Избриши све Babilim податке при деинсталацији“ у Babilim подешавањима тог сајта и поново деактивирајте. Деактивирати свакако?' . "\0" . '%1$d сајта у овој мрежи су подешена да избришу свој Babilim идентитет када се додатак обрише. Плаћена лиценца везана за те сајтове тада се не би могла аутоматски вратити; морали бисте да контактирате Babilim подршку на %2$s. Да бисте задржали идентитете, притисните Откажи, уклоните ознаку са „Избриши све Babilim податке при деинсталацији“ у Babilim подешавањима сваког сајта и поново деактивирајте. Деактивирати свакако?' . "\0" . '%1$d сајтова у овој мрежи је подешено да избришу свој Babilim идентитет када се додатак обрише. Плаћена лиценца везана за те сајтове тада се не би могла аутоматски вратити; морали бисте да контактирате Babilim подршку на %2$s. Да бисте задржали идентитете, притисните Откажи, уклоните ознаку са „Избриши све Babilim податке при деинсталацији“ у Babilim подешавањима сваког сајта и поново деактивирајте. Деактивирати свакако?','%1$s %2$s.'=>'%1$s %2$s.','%1$s (%2$s): %3$s'=>'%1$s (%2$s): %3$s','%1$s nothing to do.'=>'%1$s нема шта да се уради.','%1$s: %2$s'=>'%1$s: %2$s','%1$s: %2$s (%3$s)'=>'%1$s: %2$s (%3$s)','%1$s: %2$s. Choose the language.'=>'%1$s: %2$s. Изаберите језик.','%d failed'=>'%d неуспешно' . "\0" . '%d неуспешно' . "\0" . '%d неуспешно','%d not yet tried'=>'%d још није покушано' . "\0" . '%d још није покушано' . "\0" . '%d још није покушано','%d report is waiting. "Always share" and "Don\'t share" apply to all of them.'=>'%d извештај чека. „Always share“ и „Don\'t share“ важе за све њих.' . "\0" . '%d извештаја чекају. „Always share“ и „Don\'t share“ важе за све њих.' . "\0" . '%d извештаја чека. „Always share“ и „Don\'t share“ важе за све њих.','%d skipped'=>'%d прескочено' . "\0" . '%d прескочено' . "\0" . '%d прескочено','%d succeeded'=>'%d успешно' . "\0" . '%d успешно' . "\0" . '%d успешно','%d to install'=>'%d за инсталацију' . "\0" . '%d за инсталацију' . "\0" . '%d за инсталацију','(a public key generated for this site)'=>'(јавни кључ генерисан за овај сајт)','(detected)'=>'(откривено)','(generic codes and coordinates only)'=>'(само опште шифре и координате)','A cleanup was paused on %1$s: %2$s. Nothing was deleted.'=>'Чишћење је паузирано у %1$s: %2$s. Ништа није обрисано.','A file in the component could not be read, so it was not packaged.'=>'Датотека у компоненти није могла бити прочитана, па није спакована.','A host that serves only one PHP request at a time cannot complete this step.'=>'Хост који опslужује само један PHP захтев истовремено не може да заврши овај корак.','A part of the upload kept failing, so the upload was cancelled.'=>'Један део отпремања је стално грешио, па је отпремање отказано.','A translation cannot be requested for that locale on this site right now.'=>'Превод за тај језик тренутно се не може затражити на овом сајту.','A translation-index write conflicted with another request on %1$s (%2$s) and was not applied; the most recent version was kept.'=>'Упис у индекс превода је у сукобу са другим захтевом на %1$s (%2$s) и није примењен; задржана је најновија верзија.','A translation-index write on %1$s (%2$s) could not be completed and was not applied (%3$s).'=>'Упис у индекс превода на %1$s (%2$s) није могао бити завршен и није примењен (%3$s).','Account'=>'Налог','Add another language'=>'Додај још један језик','Advanced'=>'Напредно','All'=>'Све','All free-plan slots for this site are used'=>'Sva mesta u besplatnom paketu za ovaj Сајт su iskorišćena','All languages'=>'Сви језици','Already in WordPress core'=>'Већ у језгру Вордпреса','Already installed.'=>'Већ је инсталирано.','Always share'=>'Always share','Another installation is running; try again in a moment.'=>'Друга инсталација је у току; покушајте поново за тренутак.','Automatic installs'=>'Аутоматске инсталације','Automatic installs are now off; turn them on again in the settings if you want them.'=>'Аутоматске инсталације су сада искључене; поново их укључите у подешавањима ако желите.','Available'=>'Доступно','Available translations can be installed with one click, and missing ones can be requested. While automatic installs are on, translations the service lists as available for the languages you manage are installed during the twice-daily sync.'=>'Dostupni prevodi mogu se instalirati jednim klikom, a prevodi koji nedostaju mogu se zatražiti. Dok su automatske instalacije uključene, prevodi koje usluga navodi kao dostupne za jezike kojima upravljate instaliraju se tokom sinhronizacije dvaput dnevno.','Available · %s'=>'Доступно · %s','Babilim'=>'Babilim','Babilim Settings'=>'Babilim подешавања','Babilim adds translations for every language checked here.'=>'Babilim додаје преводе за сваки овде означен језик.','Babilim could not confirm a temporary folder outside the website, so the component was not packaged and nothing was uploaded. Define BABILIM_TEMP_DIR in wp-config.php as a writable folder outside the web root (for example a folder next to, not inside, your site\'s public directory), or ask your host for one.'=>'Babilim није могао да потврди привремену фасциклу изван веб-сајта, па компонента није упакована и ништа није отпремљено. Дефинишите BABILIM_TEMP_DIR у wp-config.php као фасциклу са дозволом писања изван веб корена (на пример фасцикла поред јавног директоријума вашег сајта, а не унутар њега) или је затражите од свог хостинга.','Babilim could not finish checking this site.'=>'Babilim није могао да заврши проверу овог сајта.','Babilim could not finish enabling (%1$s): %2$s'=>'Babilim није могао да заврши омогућавање (%1$s): %2$s','Babilim could not finish verifying this site (the service could not reach it back). Registration is paused.'=>'Babilim није могао да заврши проверу овог сајта (услуга није могла да му приступи). Регистрација је паузирана.','Babilim could not verify this site, so nothing is downloaded or installed until verification succeeds.'=>'Babilim није могао да потврди овај сајт, па се ништа неће преузимати нити инсталирати док потврда не успе.','Babilim could not verify this site, so nothing is downloaded or installed.'=>'Babilim није могао да верификује овај сајт, па се ништа не преузима нити инсталира.','Babilim gets translations from the Babilim service for the plugins and themes on this site that have none for your language, and installs the ones your service plan covers.'=>'Babilim преузима преводе из Babilim servisa за додатке и теме на овом сајту који немају превод на ваш језик и инсталира оне које покрива ваш plan usluge.','Babilim has not been enabled for this site yet.'=>'Babilim још није омогућен за овај сајт.','Babilim has not installed any translation for this language.'=>'Babilim није инсталирао ниједан превод за овај језик.','Babilim hit an error. Share an error report?'=>'Babilim је наишао на грешку. Желите ли да поделите извештај о грешци?','Babilim installed %d translation automatically since your last visit.'=>'Babilim је аутоматски инсталирао %d превод од ваше последње посете.' . "\0" . 'Babilim је аутоматски инсталирао %d превода од ваше последње посете.' . "\0" . 'Babilim је аутоматски инсталирао %d превода од ваше последње посете.','Babilim is disabled. Nothing more is sent; translations already installed keep working.'=>'Babilim је онемогућен. Више се ништа не шаље; већ инсталирани преводи настављају да раде.','Babilim is enabled: this site is verified and %d component was found.'=>'Babilim је омогућен: овај сајт је верификован и пронађена је %d компонента.' . "\0" . 'Babilim је омогућен: овај сајт је верификован и пронађене су %d компоненте.' . "\0" . 'Babilim је омогућен: овај сајт је верификован и пронађено је %d компоненти.','Babilim is enabling and checking this site… (last attempt: %s)'=>'Babilim омогућава и проверава овај сајт… (последњи покушај: %s)','Babilim is enabling and checking this site… Reload this page or wait for the scheduled check to finish.'=>'Babilim омогућава и проверава овај сајт… Поново учитајте страницу или сачекајте да се заказана провера заврши.','Babilim is not enabled.'=>'Babilim није омогућен.','Babilim is set to erase this site\'s identity when the plugin is deleted. The paid license attached to this site could then not be restored automatically; you would have to contact Babilim support at %s. To keep the identity, press Cancel, untick "Delete all Babilim data on uninstall" in the Babilim settings, and deactivate again. Deactivate anyway?'=>'Babilim је подешен да избрише идентитет овог сајта када се додатак обрише. Плаћена лиценца везана за овај сајт тада се не би могла аутоматски вратити; морали бисте да контактирате Babilim подршку на %s. Да бисте задржали идентитет, притисните Откажи, уклоните ознаку са „Избриши све Babilim податке при деинсталацији“ у Babilim подешавањима и поново деактивирајте. Деактивирати свакако?','Babilim ran out of time for this step and will continue on the next check.'=>'Babilim је остао без времена за овај корак и наставиће при следећој провери.','Babilim settings'=>'Babilim подешавања','Babilim sync is temporarily delayed by the service (rate limited); it will try again after %s.'=>'Babilim синхронизација је привремено одложена од стране сервиса (ограничење броја захтева); покушаће поново након %s.','Babilim was updated while this upload was waiting. The old package was discarded; please confirm the upload again.'=>'Babilim је ажуриран док је ово отпремање чекало. Стари пакет је одбачен; поново потврдите отпремање.','Babilim will upload these files from %1$s (version %2$s): every .php and .js file, every block.json file, and the readme.txt, readme.md, style.css and theme.json in its main folder. They are used to find the text that needs translating and to identify the plugin or theme.'=>'Babilim ће отпремити ове датотеке из %1$s (верзија %2$s): сваку .php и .js датотеку, сваку block.json датотеку, као и readme.txt, readme.md, style.css и theme.json у његовој главној фасцикли. Користе се за проналажење текста који треба превести и за идентификацију додатка или теме.','Babilim_Manifest is unavailable: %s'=>'Babilim_Manifest није доступан: %s','Back'=>'Назад','Bought a license for this domain before? Enter the restore code you received at checkout.'=>'Већ сте купили лиценцу за овај домен? Унесите код за враћање који сте добили при куповини.','Broken placeholder'=>'Покварен чувар места','Build'=>'Верзија','Built'=>'Изграђено','Bulk actions apply only to the selected language of each selected component.'=>'Групне радње се примењују само на изабрани језик сваке изабране компоненте.','Bulk actions apply to every matching language of each selected component.'=>'Групне радње се примењују на сваки одговарајући језик сваке изабране компоненте.','Bulk download:'=>'Групно преузимање:','Bulk request:'=>'Групни захтев:','Bulk update:'=>'Групно ажурирање:','Bundled with the plugin'=>'Укључено уз додатак','Bundled with the theme'=>'Укључено уз тему','By clicking Enable, you agree to send the information listed above to Babilim.'=>'Кликом на Омогући пристајете да информације наведене изнад пошаљете сервису Babilim.','By continuing you confirm that you have the right to upload this component.'=>'Настављањем потврђујете да имате право да отпремите ову компоненту.','Cancel'=>'Откажи','Category'=>'Категорија','Check again'=>'Провери поново','Check again now'=>'Провери поново сада','Checkout is not available for this site right now.'=>'Наплата тренутно није доступна за овај сајт.','Choose'=>'Изабери','Choose a category…'=>'Изаберите категорију…','Choose a language'=>'Изаберите језик','Choose a language…'=>'Изаберите језик…','Clear filters'=>'Обриши филтере','Close'=>'Затвори','Component'=>'Компонента','Confirm'=>'Потврди','Conflicting keys'=>'Конфликтни кључеви','Continue'=>'Настави','Continue next batch (%d left)'=>'Настави са следећом групом (преостало: %d)','Continuing…'=>'Настављање…','Could not back up %s before replacing it.'=>'Није могуће направити резервну копију %s пре замене.','Could not create the package archive.'=>'Није могуће направити архиву пакета.','Could not determine active components; the existing merged index was left unchanged.'=>'Није могуће утврдити активне компоненте; постојећи спојени индекс је остављен непромењен.','Could not determine installed plugins/themes; sweep skipped, nothing was deleted.'=>'Није могуће утврдити инсталиране додатке/теме; чишћење је прескочено, ништа није обрисано.','Could not load the full WordPress.org locale list from the service, so no other language can be added right now.'=>'Није могуће учитати потпуну листу језичких поставки WordPress.org са сервиса, па тренутно није могуће додати још неки језик.','Could not move %s into place.'=>'Није могуће преместити %s на место.','Could not move the merged index for \'%s\' into place; the previous served index (if any) was removed rather than left half-updated. No default-domain supplement is served for this locale until the next successful rebuild.'=>'Није могуће поставити обједињени индекс за „%s“ на место; претходни индекс који је био у употреби (ако га је било) уклоњен је уместо да буде остављен напола ажуриран. Допуна подразумеваног домена није доступна за ову језичку поставку до следеће успешне поновне изградње.','Could not open zip: %s'=>'Није могуће отворити zip: %s','Could not prepare %s for rollback.'=>'Није могуће припремити %s за враћање на претходно стање.','Could not read %s back after moving it into place.'=>'Није могуће поново прочитати %s након премештања на место.','Could not read: %s'=>'Није могуће прочитати: %s','Could not restore the purchase: %s'=>'Није могуће вратити куповину: %s','Could not show a new restore code: %s'=>'Није могуће приказати нови код за враћање: %s','Could not stage %s'=>'Није могуће припремити %s','Could not stage default/%s'=>'Није могуће припремити default/%s','Could not start checkout: %s'=>'Није могуће покренути наплату: %s','Could not verify entry count for %s'=>'Није могуће проверити број уноса за %s','Could not write the downloaded package to disk.'=>'Преузети пакет није могао да се упише на диск.','Could not write the staged merged index.'=>'Није могуће записати припремљени обједињени индекс.','Current translation'=>'Тренутни превод','Custom overrides'=>'Сопствена замењивања','Danger zone'=>'Опасна зона','Default supplement entry count mismatch.'=>'Број уноса у допуни за домен default се не поклапа.','Delete all Babilim data on uninstall'=>'Избриши све Babilim податке при деинсталацији','Disable Babilim'=>'Искључи Babilim','Disable Babilim? Installed translations are kept, but no further checks or downloads will run.'=>'Искључити Babilim? Инсталирани преводи се задржавају, али се више неће вршити провере нити преузимања.','Don\'t share'=>'Don\'t share','Download'=>'Преузми','Downloaded and installed.'=>'Преузето и инсталирано.','Downloading…'=>'Преузимање…','Downloads: %1$d/%2$d (%3$s)'=>'Преузимања: %1$d/%2$d (%3$s)','Each component\'s own contribution to each locale\'s shared default-domain supplement.'=>'Допринос сваке компоненте заједничкој допуни подразумеваног домена сваког језика.','Enable Babilim'=>'Омогући Babilim','Enabling…'=>'Омогућавање…','English (United States)'=>'Енглески (Сједињене Америчке Државе)','Entries'=>'Уноси','Entry count mismatch for %s'=>'Број уноса се не поклапа за %s','Error reports'=>'Извештаји о грешкама','Every locale in use on this site (site locale, installed language packs, user locales, and any you add manually). No locale is treated differently from another.'=>'Сваки језик који се користи на овом сајту (језик сајта, инсталирани језички пакети, језици корисника и сви које ручно додате). Ниједан језик се не третира другачије од другог.','Excluded'=>'Изузето','Files with other names or extensions are not included, nor are the uploads, cache, logs, backup, data, vendor, node_modules and languages folders, hidden files, or files whose names match common secrets (wp-config*, .env*, *.sql, *.log, *.pem, *.key). Code files can still contain text or data you would not want to share; check them if you are unsure. The service removes the same kinds of files again on arrival.'=>'Датотеке са другачијим именима или наставцима нису укључене, као ни фасцикле uploads, cache, logs, backup, data, vendor, node_modules и languages, скривене датотеке, нити датотеке чија се имена поклапају са уобичајеним тајним подацима (wp-config*, .env*, *.sql, *.log, *.pem, *.key). Датотеке кода и даље могу садржати текст или податке које не бисте желели да делите; проверите их ако нисте сигурни. Сервис при пријему поново уклања исте врсте датотека.','Fills in missing translations for the plugins and themes already installed on your site.'=>'Допуњује преводе који недостају за додатке и теме већ инсталиране на вашем сајту.','Free'=>'Бесплатно','Free-plan slots'=>'Mesta u besplatnom paketu','General'=>'Опште','If this is on, uninstalling also erases this site\'s identity. The paid license attached to this site cannot be restored automatically afterwards; you would have to contact Babilim support at %s to get it back.'=>'Ако је ово укључено, деинсталација такође брише идентитет овог сајта. Плаћена лиценца везана за овај сајт након тога се не може аутоматски вратити; морали бисте да контактирате Babilim подршку на %s да бисте је повратили.','Included'=>'Укључено','Included in index'=>'Укључено у индекс','Install available translations automatically'=>'Аутоматски инсталирај доступне преводе','Installed'=>'Инсталирано','Installed translations are kept, but no further checks or downloads will run.'=>'Инсталирани преводи се задржавају, али се више неће вршити провере нити преузимања.','Installed · %s'=>'Инсталирано · %s','Installed · built for %1$s, this site has %2$s'=>'Инсталирано · направљено за %1$s, овај сајт има %2$s','Installed · built for %s'=>'Инсталирано · направљено за %s','Installed · built for %s, new version failed'=>'Инсталирано · направљено за %s, нова верзија није успела','Installed · built for %s, new version scheduled'=>'Инсталирано · направљено за %s, нова верзија је заказана','Installed · built for %s, translating the new version…'=>'Инсталирано · направљено за %s, превођење нове верзије…','Installed · built for %s; this plugin or theme is no longer covered by the site\'s service plan'=>'Инсталирано · направљено за %s; овај додатак или тема више није покривен планом услуге сајта','Installed · built for a different version'=>'Инсталирано · направљено за другу верзију','Installed · built for a different version, new version failed'=>'Инсталирано · направљено за другу верзију, нова верзија није успела','Installed · built for a different version, new version scheduled'=>'Инсталирано · направљено за другу верзију, нова верзија је заказана','Installed · built for a different version, translating the new version…'=>'Инсталирано · направљено за другу верзију, превођење нове верзије…','Installed · built for a different version; this plugin or theme is no longer covered by the site\'s service plan'=>'Инсталирано · направљено за другу верзију; овај додатак или тема више није покривен планом услуге сајта','It is stored by the service\'s hosting provider and processed by AI models to produce the translation.'=>'Чува га добављач хостинга услуге, а AI модели га обрађују да би направили превод.','Keep my own translation overrides when purging everything or uninstalling this plugin.'=>'Задржи моја сопствена замењивања превода при брисању свега или деинсталацији овог додатка.','Language'=>'Језик','Language:'=>'Језик:','Languages'=>'Језици','Languages found on this site: %s.'=>'Језици пронађени на овом сајту: %s.','Last cleanup on %1$s: %2$d newly marked, %3$d file(s) deleted, %4$d record(s) removed.'=>'Последње чишћење у %1$s: ново означених: %2$d, обрисаних датотека: %3$d, уклоњених записа: %4$d.','Maintenance'=>'Одржавање','Maintenance status is not available right now.'=>'Статус одржавања тренутно није доступан.','Manifest unavailable: %s'=>'Манифест није доступан: %s','Negation reversed'=>'Негација је обрнута','No'=>'Не','No build is available to download for this locale.'=>'Нема доступне верзије за преузимање за овај језик.','No cleanup has run yet.'=>'Чишћење још није покренуто.','No components match these filters. %s'=>'Ниједна компонента не одговара овим филтерима. %s','No components synced yet.'=>'Још ниједна компонента није синхронизована.','No installed translation matches.'=>'Nijedan инсталирани превод не одговара.','No language is managed yet.'=>'Још ниједан језик није под управом.','No pending challenge for this nonce.'=>'Нема изазова на чекању за овај nonce.','No pending challenge to verify.'=>'Нема изазова на чекању за потврду.','No plugins or themes found.'=>'Нису пронађени додаци ни теме.','No previous build to roll back to.'=>'Нема претходне изградње на коју би се могло вратити.','No record for %s'=>'Нема записа за %s','No site id is on file to rotate a token for.'=>'Није сачуван ID сајта за који би се ротирао токен.','No — component inactive'=>'Не — компонента је неактивна','No — component removed'=>'Не — компонента је уклоњена','No — installed version differs from the active one'=>'Не — инсталирана верзија се разликује од активне','Not a valid server_build_id: %s'=>'Није важећи server_build_id: %s','Not covered by the free service plan'=>'Nije obuhvaćeno besplatnim paketom usluge','Not installed'=>'Nije instalirano','Not registered yet'=>'Још није регистровано','Not supported'=>'Није подржано','Not verified'=>'Није верификовано','Note (optional)'=>'Напомена (необавезно)','Nothing to choose.'=>'Нема шта да се изабере.','Nothing to confirm.'=>'Нема шта да се потврди.','Off by default: deleting the plugin keeps this site\'s identity, so a reinstall can reuse it.'=>'Подразумевано искључено: брисање додатка задржава идентитет овог сајта, па га поновна инсталација може поново користити.','One or more served files no longer match the manifest.'=>'Једна или више послужених датотека више не одговара манифесту.','One-time purchase for this site: %1$s %2$s. Includes all future translation updates. Payment is handled by Paddle in a new tab.'=>'Једнократна куповина за овај сајт: %1$s %2$s. Укључује сва будућа ажурирања превода. Плаћањем управља Paddle у новој картици.','Only a network administrator can do this, because it changes translation files shared by every site on this network.'=>'Ово може да уради само администратор мреже, јер се мењају датотеке превода које деле сви сајтови у овој мрежи.','Only plugins and themes can be packaged.'=>'Могу се паковати само додаци и теме.','Only when you confirm an upload for a plugin or theme that is not on WordPress.org: every .php and .js file, every block.json file, and the readme.txt, readme.md, style.css and theme.json in that component\'s main folder, as a zip, after files that match common secrets are left out.'=>'Само када потврдите отпремање за додатак или тему који нису на WordPress.org: сваку .php и .js датотеку, сваку block.json датотеку, као и readme.txt, readme.md, style.css и theme.json у главној фасцикли те компоненте, као zip, након што се изоставе датотеке које одговарају уобичајеним тајним подацима.','Open Babilim settings'=>'Отвори Babilim подешавања','Original language'=>'Изворни језик','Original string'=>'Изворна ниска','Paid'=>'Plaćeno','Partner'=>'Партнер','Please check that your site can be reached from the internet, then try again.'=>'Проверите да ли је ваш сајт доступан са интернета, а затим покушајте поново.','Please choose a category for this report.'=>'Изаберите категорију за овај извештај.','Plugin'=>'Додатак','Plugin · %s'=>'Додатак · %s','Plugins'=>'Додаци','Preview'=>'Преглед','Purchase restored. This site is now licensed.'=>'Куповина је враћена. Овај сајт је сада лиценциран.','Re-parsed entry count did not match the built index.'=>'Број уноса поново обрађеног индекса не одговара изграђеном индексу.','Re-verify'=>'Поново верификуј','Rebuild index now'=>'Обнови индекс сада','Refusing to write outside the Babilim language-file directory.'=>'Одбијено је писање изван директоријума језичких датотека Babilim.','Registration response was missing required fields.'=>'У одговору на регистрацију недостају обавезна поља.','Registration restarted.'=>'Регистрација је поново покренута.','Remove'=>'Уклони','Remove everything Babilim installed'=>'Уклони све што је Babilim инсталирао','Remove everything Babilim installed? This deletes every language file it installed for every plugin and theme on this site.'=>'Уклонити све што је Babilim инсталирао? Ово брише сваку датотеку језика коју је инсталирао за сваки додатак и сваку тему на овом сајту.','Remove the %2$s translation of %1$s from this site?'=>'Уклонити %2$s превод за %1$s са овог сајта?','Removed %d installed component.'=>'Уклоњена је %d инсталирана компонента.' . "\0" . 'Уклоњене су %d инсталиране компоненте.' . "\0" . 'Уклоњено је %d инсталираних компоненти.','Removed after a failed integrity check'=>'Уклоњено после неуспеле провере интегритета','Removed.'=>'Уклоњено.','Removes every language file Babilim has installed for every plugin and theme on this site.'=>'Уклања сваку датотеку за Језик коју је Babilim инсталирао за сваки додатак и тему на овом сајту.','Report a problem'=>'Пријави проблем','Report translation'=>'Пријави превод','Request newer translation'=>'Затражи новији превод','Request translation'=>'Затражи превод','Requestable'=>'Може се захтевати','Requesting a translation puts this plugin or theme on one of the free service plan\'s slots for this site (the limit is %1$d for themes and %2$d for plugins), unless it already has one. A slot stays used, and a failed translation does not free it.'=>'Захтевањем превода овај додатак или тема заузима један од слотова бесплатног пакета услуге за овај сајт (ограничење је %1$d за теме и %2$d за додатке), осим ако већ има слот. Слот остаје заузет, а неуспео превод га не ослобађа.','Requesting a translation puts this plugin or theme on one of the free service plan\'s slots for this site, unless it already has one. A slot stays used, and a failed translation does not free it.'=>'Захтевањем превода овај додатак или тема заузима један од слотова бесплатног пакета услуге за овај сајт, осим ако већ има слот. Слот остаје заузет, а неуспео превод га не ослобађа.','Requesting…'=>'Захтевање…','Restart registration'=>'Поново покрени регистрацију','Restore code'=>'Код за враћање','Restore purchase'=>'Врати куповину','Retry request'=>'Покушај захтев поново','Roll back'=>'Врати на претходно','Roll back and report'=>'Врати на претходно и пријави','Roll back and send report'=>'Врати и пошаљи извештај','Roll back the %2$s translation of %1$s to the previous build?'=>'Вратити превод %2$s за %1$s на претходну верзију изградње?','Rolled back and reported.'=>'Враћено и пријављено.','Rolled back to the previous build.'=>'Враћено на претходну верзију.','Rolled back, but the report could not be sent: %s'=>'Враћено на претходну верзију, али извештај није могао бити послат: %s','Rolling back would overwrite \'%1$s\' (%2$s), which is now served for another installed component (%3$s); nothing was changed.'=>'Враћање на претходно стање би преписало „%1$s“ (%2$s), која се сада служи за другу инсталирану компоненту (%3$s); ништа није промењено.','Rotate-token response was missing site_token.'=>'У одговору на ротацију токена недостаје site_token.','Save changes'=>'Сачувај промене','Scheduled, waiting to be processed'=>'Заказано, чека на обраду','Search'=>'Претражи','Search components'=>'Претражи компоненте','Search the installed translations'=>'Претражи инсталиране преводе','Select all'=>'Изабери све','Select fewer components: at most %1$d operations per run (you selected %2$d).'=>'Изаберите мање компоненти: највише %1$d операција по покретању (изабрали сте %2$d).','Send report'=>'Пошаљи извештај','Service plan'=>'Paket usluge','Settings'=>'Подешавања','Share error reports'=>'Дели извештаје о грешкама','Share this report'=>'Подели овај извештај','Show a new restore code'=>'Прикажи нови код за враћање','Show the "Report translation" entry in the admin toolbar'=>'Prikaži stavku „Prijavi prevod“ na traci sa alatkama za administraciju','Some of this component\'s text is hard-coded by its author and can\'t be translated by a language pack.'=>'Аутор је део текста ове компоненте уписао директно у код, па тај текст не може да се преведе помоћу пакета за језик.','Status'=>'Статус','Status unknown'=>'Статус је непознат','String context'=>'Контекст стринга','Suggested translation'=>'Предложени превод','Supplementary translation index'=>'Индекс додатних превода','Supplementary translation index rebuilt.'=>'Допунски индекс превода је поново изграђен.','Supplementary translation maintenance'=>'Одржавање допунских превода','Supplementary translations'=>'Додатни преводи','Sweep aborted without orphaning anything: %s.'=>'Чишћење је прекинуто без остављања иједног сирочета: %s.','Sweep complete: %d file deleted.'=>'Чишћење је завршено: %d датотека је избрисана.' . "\0" . 'Чишћење је завршено: %d датотеке су избрисане.' . "\0" . 'Чишћење је завршено: %d датотека је избрисано.','Sweep now'=>'Очисти сада','Sync complete.'=>'Синхронизација је завршена.','Thank you. Your report was sent.'=>'Хвала. Ваш извештај је послат.','That component is not installed on this site, so a translation cannot be requested for it.'=>'Та компонента није инсталирана на овом сајту, па се за њу не може затражити превод.','That does not look like a restore code.'=>'Ово не изгледа као код за враћање.','That is not a valid WordPress locale code. Nothing was saved.'=>'То није исправан Вордпрес код језика. Ништа није сачувано.','That is not a valid build identifier.'=>'То није важећи идентификатор верзије изградње.','That upload screen was out of date: a different upload has been prepared since. Nothing was sent. Review the current one from the Translations list.'=>'Тај екран за отпремање је застарео: у међувремену је припремљено другачије отпремање. Ништа није послато. Погледајте тренутно отпремање на Списку превода.','The change could not be recorded in the translation index; please try again.'=>'Промена није могла бити записана у индекс превода; покушајте поново.','The cleanup ran, but some of its changes could not be recorded in the translation index; the next cleanup will retry them.'=>'Чишћење је покренуто, али неке његове промене није било могуће записати у индекс превода; следеће чишћење ће их поново покушати.','The component has no files that can be uploaded.'=>'Компонента нема датотека које се могу отпремити.','The component is not inside the plugins or themes directory.'=>'Компонента није унутар директоријума са додацима или темама.','The component\'s main file was not found.'=>'Главна датотека компоненте није пронађена.','The download response was missing a usable location.'=>'У одговору на преузимање недостаје употребљива локација.','The entry opens a panel to search the translations Babilim installed on this site and report one of them.'=>'Stavka otvara panel za pretragu prevoda koje je Babilim instalirao na ovom Сајту i za prijavu nekog od njih.','The field "%1$s" is too long: it has %2$d characters and the limit is %3$d. Nothing was sent; please shorten it and try again.'=>'Поље „%1$s“ је предугачко: има %2$d знакова, а ограничење је %3$d. Ништа није послато; скратите га и покушајте поново.','The free service plan gives each site a limited number of slots for plugins and themes; the slots in use are shown in Settings after you enable Babilim.'=>'Бесплатни пакет услуге даје сваком сајту ограничен број слотова за додатке и теме; слотови у употреби приказани су у Подешавањима након што омогућите Babilim.','The given domain \'%1$s\' matches neither the package manifest\'s own slug \'%2$s\' nor its text_domain \'%3$s\'.'=>'Наведени домен „%1$s“ не одговара ни сопственом слагу манифеста пакета „%2$s“ ни његовом text_domain „%3$s“.','The merged index for \'%s\' was rebuilt, but the translation index could not record it; the next rebuild will retry.'=>'Спојени индекс за „%s“ је поново изграђен, али индекс превода није могао да га забележи; следећа поновна изградња ће покушати поново.','The original text and the translations made from it will be provided to other sites that install the same version.'=>'Оригинални текст и преводи направљени на основу њега биће дати другим сајтовима који инсталирају исту верзију.','The package declares no main translation file.'=>'Пакет не декларише главну датотеку превода.','The package has no %s for its own text domain.'=>'Пакет нема %s за сопствени текстуални домен.','The package manifest\'s kind \'%1$s\' does not match the requested kind \'%2$s\'.'=>'Врста манифеста пакета „%1$s“ не одговара захтеваној врсти „%2$s“.','The package produced no servable main translation file.'=>'Пакет није произвео употребљиву главну датотеку превода.','The package\'s text domain \'%1$s\' does not match this site\'s copy of the component (\'%2$s\'), so it was not installed.'=>'Текстуални домен пакета „%1$s“ не одговара копији компоненте на овом сајту („%2$s“), па није инсталиран.','The packaged component could not be read.'=>'Спакована компонента није могла бити прочитана.','The registration challenge is not in the expected form.'=>'Изазов за регистрацију није у очекиваном облику.','The report could not be sent.'=>'Извештај није могао бити послат.','The search could not be completed.'=>'Претрага није могла бити завршена.','The service asked this site to wait before syncing again.'=>'Услуга је затражила да овај сајт сачека пре следеће синхронизације.','The service could not reach your site. A firewall, security plugin or host rule is probably blocking the request; please allow requests to /wp-json/babilim/v1/challenge.'=>'Сервис није могао да допре до вашег сајта. Вероватно захтев блокира заштитни зид, безбедносни додатак или правило хостинга; дозволите захтеве ка /wp-json/babilim/v1/challenge.','The service\'s upload offer was incomplete.'=>'Понуда услуге за отпремање била је непотпуна.','The text domain \'%1$s\' (%2$s) is already served for another installed component (%3$s); nothing was installed.'=>'Текстуални домен „%1$s“ (%2$s) већ се служи за другу инсталирану компоненту (%3$s); ништа није инсталирано.','The upload is kept until you ask Babilim to delete it.'=>'Отпремљени садржај се чува док не затражите од Babilim-а да га избрише.','Theme'=>'Тема','Theme · %s'=>'Тема · %s','Themes'=>'Теме','There is no upload in progress.'=>'Отпремање није у току.','There is no upload waiting for confirmation.'=>'Нема отпремања које чека потврду.','These are the languages this site uses. You can change them in %s.'=>'Ово су језици које овај сајт користи. Можете их променити у %s.','These fields will be sent:'=>'Ова поља ће бити послата:','This build is not one this site currently knows about for this component/locale.'=>'Овај сајт тренутно не познаје ову верзију за ову компоненту/језик.','This component does not declare a version number, so a translation cannot be requested for it.'=>'Ова компонента не наводи број верзије, па се за њу не може затражити превод.','This component is larger than the service accepts, so it cannot be uploaded.'=>'Ова компонента је већа него што услуга прихвата, па се не може отпремити.','This component was already uploaded. Babilim is checking it now.'=>'Ова компонента је већ отпремљена. Babilim је сада проверава.','This component\'s version number is longer than %d characters, which Babilim cannot handle, so a translation cannot be requested for it.'=>'Број верзије ове компоненте је дужи од %d знакова, што Babilim не може да обради, па се за њу не може затражити превод.','This issues a new restore code and the previous one stops working. Continue?'=>'Ово издаје нови код за враћање, а претходни престаје да важи. Желите ли да наставите?','This network has too many sites to check them one by one, and some of them may be set to erase their Babilim identity when the plugin is deleted. The paid license attached to such a site could then not be restored automatically; you would have to contact Babilim support at %s. To keep the identities, press Cancel, untick "Delete all Babilim data on uninstall" in each site\'s Babilim settings, and deactivate again. Deactivate anyway?'=>'Ова мрежа има превише сајтова да би се проверавали један по један, а неки од њих можда су подешени да избришу свој Babilim идентитет када се додатак обрише. Плаћена лиценца везана за такав сајт тада се не би могла аутоматски вратити; морали бисте да контактирате Babilim подршку на %s. Да бисте задржали идентитете, притисните Откажи, уклоните ознаку са „Избриши све Babilim податке при деинсталацији“ у Babilim подешавањима сваког сајта и поново деактивирајте. Деактивирати свакако?','This plugin\'s own version, so the service can tell you to update it if it\'s too old to talk to.'=>'Верзија самог овог додатка, да би вас услуга могла упозорити да га ажурирате ако је престар за комуникацију.','This report does not name a valid plugin or theme and locale.'=>'Овај извештај не наводи исправан додатак или тему и језик.','This report does not name an installed string.'=>'Овај извештај не наводи ниједан инсталирани стринг.','This report is missing a valid build to report against.'=>'Овом извештају недостаје исправна верзија на коју се односи.','This report will be posted publicly on GitHub and may be kept by third parties.'=>'Овај извештај ће бити јавно објављен на GitHub-у и трећа лица могу да га задрже.','This restore code was not recognised for this site.'=>'Овај код за враћање није препознат за овај сајт.','This site already has an active registration that can no longer be recovered automatically.'=>'Овај сајт већ има активну регистрацију која се више не може аутоматски опоравити.','This site has %1$d components across %2$d languages, which needs %3$d check batches; Babilim can handle at most %4$d per run. Reduce the managed languages in Settings or deactivate unused plugins and themes, then press Check again now.'=>'Овај сајт има %1$d компоненти на %2$d језика, што захтева %3$d пакета провере; Babilim може да обради највише %4$d по покретању. Смањите број управљаних језика у Подешавањима или деактивирајте некоришћене додатке и теме, а затим одмах притисните Провери поново.','This site has no purchase to show a code for.'=>'Овај сајт нема куповину за коју би се приказао код.','This site is already licensed. Reload the page.'=>'Овај сајт је већ лиценциран. Поново учитајте страницу.','This site is not registered with Babilim yet.'=>'Овај сајт још није регистрован код Babilim-а.','This site is over the size the service accepts in one sync, so some items were left out: %1$d components and %2$d locales.'=>'Овај сајт прелази величину коју сервис прихвата у једној синхронизацији, па су неке ставке изостављене: %1$d компоненти и %2$d језичких варијанти.','This site is part of a multisite network, which does not install new translations automatically. Translations that are already installed are still updated.'=>'Овај сајт је део мултисајт мреже, која не инсталира нове преводе аутоматски. Већ инсталирани преводи се и даље ажурирају.','This site is verified.'=>'Овај сајт је верификован.','This site must be verified first.'=>'Овај сајт прво мора бити верификован.','This site\'s URL, so the service can verify you own it.'=>'URL овог сајта, да би услуга могла да потврди да сте његов власник.','This site\'s address is too long for Babilim to register.'=>'Адреса овог сајта је предугачка да би је Babilim регистровао.','This site\'s configured locale.'=>'Подешени локалитет овог сајта.','This site\'s locale code is not one Babilim can register.'=>'Кôд локалитета овог сајта није један од оних које Babilim може да региструје.','This string can\'t be reported from this site.'=>'Овај стринг се не може пријавити са овог сајта.','This string is not among the translations installed on this site. Search again and pick it from the list.'=>'Овај стринг није међу преводима инсталираним на овом сајту. Претражите поново и изаберите га са листе.','This translation was updated since you searched. Search again and pick the string from the new list.'=>'Овај превод је ажуриран откако сте претраживали. Претражите поново и изаберите стринг са нове листе.','To translate this component, Babilim needs its source.'=>'За превођење ове компоненте Babilim-у је потребан њен изворни код.','Too many attempts. Try again tomorrow.'=>'Превише покушаја. Покушајте поново сутра.','Too many reports today. Try again tomorrow.'=>'Превише пријава данас. Покушајте поново сутра.','Too many requests.'=>'Превише захтева.','Toolbar'=>'Traka sa alatkama','Translating…'=>'Превођење…','Translation does not load'=>'Превод се не учитава','Translation failed'=>'Превод није успео','Translation files you put in %s always take priority over Babilim\'s. They are kept unless you uncheck this.'=>'Датотеке превода које ставите у %s увек имају приоритет над Babilim датотекама. Задржавају се осим ако ово не искључите.','Translation requested.'=>'Превод је затражен.','Translations'=>'Преводи','Type'=>'Тип','Type at least 2 characters to search.'=>'Унесите најмање 2 знака за претрагу.','Unexpected HTTP %d response.'=>'Неочекиван HTTP одговор %d.','Uninstall'=>'Деинсталација','Unknown kind: %s'=>'Непозната врста: %s','Unsafe domain: %s'=>'Небезбедан домен: %s','Unsafe locale: %s'=>'Небезбедна ознака језичке поставке: %s','Unsafe slug: %s'=>'Небезбедан слаг: %s','Unsafe text_domain: %s'=>'Небезбедан text_domain: %s','Update'=>'Ажурирај','Update available'=>'Доступно ажурирање','Updates'=>'Ажурирања','Updating…'=>'Ажурирање…','Upgrade this site'=>'Надогради овај сајт','Upload and request'=>'Отпреми и затражи','Upload cancelled.'=>'Отпремање је отказано.','Upload complete — translation requested.'=>'Отпремање је завршено — превод је затражен.','Upload expired before it finished'=>'Отпремање је истекло пре завршетка','Upload in progress — continue or cancel'=>'Отпремање је у току — наставите или откажите','Upload this component?'=>'Отпреми ову компоненту?','Upload was not accepted'=>'Отпремање није прихваћено','Uploading'=>'Отпремање','Uploading part %1$d of %2$d…'=>'Отпремање дела %1$d од %2$d…','Uploading…'=>'Отпремање…','Verified'=>'Верификовано','Verify response was missing site_token.'=>'У одговору на потврду недостаје site_token.','Version %s'=>'Верзија %s','What is sent when you enable Babilim'=>'Шта се шаље када омогућите Babilim','When something fails inside Babilim, send an error report to the Babilim service so it can be published as a public issue on GitHub. The report is sent as coming from this site, with the same authentication as every other request to the Babilim service. The service publishes only the error code and versions as a public issue on GitHub; the public issue contains no site address, content or file paths. Off by default.'=>'Када нешто закаже унутар Babilim-а, пошаљите извештај о грешци Babilim услузи да би могао бити објављен као јавни проблем на GitHub-у. Извештај се шаље као да долази са овог сајта, уз исту аутентикацију као и сваки други захтев упућен Babilim услузи. Услуга објављује само код грешке и верзије као јавни проблем на GitHub-у; јавни проблем не садржи адресу сајта, садржај нити путање до датотека. Подразумевано је искључено.','Where you saw this (optional)'=>'Где сте ово видели (необавезно)','While this is on, translations the service lists as available for the languages you manage are installed during the twice-daily sync.'=>'Dok je ovo uključeno, prevodi koje usluga navodi kao dostupne za jezike kojima upravljate instaliraju se tokom sinhronizacije dvaput dnevno.','WordPress.org'=>'WordPress.org','Wrong for this context'=>'Погрешно за овај контекст','Wrong meaning'=>'Погрешно значење','Wrong plural form'=>'Погрешан облик множине','Wrong term'=>'Погрешан термин','Yes'=>'Да','You are not allowed to do this.'=>'Није вам дозвољено да то урадите.','Your PHP version, for compatibility.'=>'Ваша верзија PHP-а, ради компатибилности.','Your WordPress version, to serve compatible translation files.'=>'Ваша верзија Вордпреса, ради испоруке компатибилних датотека превода.','Your new restore code: %s. Keep it somewhere safe — the previous code no longer works.'=>'Ваш нови код за враћање: %s. Чувајте га на сигурном месту — претходни код више не важи.','Your report is processed automatically by AI models and may improve this translation for other sites.'=>'Ваш извештај аутоматски обрађују AI модели и може побољшати овај превод за друге сајтове.','Your site answered, but not with what was expected. The REST API may be rewritten by another plugin, or that endpoint may be cached; please exclude /wp-json/babilim/v1/challenge from caching and rewriting.'=>'Ваш сајт је одговорио, али не оним што се очекивало. REST API можда преписује други додатак, или је та крајња тачка кеширана; изузмите /wp-json/babilim/v1/challenge из кеширања и преписивања.','Your site took too long to answer. Please try again later, and check that your host is not too slow or overloaded.'=>'Ваш сајт је предуго одговарао. Покушајте поново касније и проверите да хостинг није превише спор или преоптерећен.','Zip has no manifest.json.'=>'Zip нема manifest.json.','Zip is missing expected default file: %s'=>'У zip недостаје очекивана подразумевана датотека: %s','Zip is missing expected file: %s'=>'У zip недостаје очекивана датотека: %s','_manifest.json has an unexpected structure'=>'Датотека _manifest.json има неочекивану структуру','could not read _manifest.json: %s'=>'није могуће прочитати _manifest.json: %s','expected_manifest is missing or has an invalid \'%s\'.'=>'expected_manifest недостаје или има неважеће поље „%s“.','expected_manifest\'s \'server_build_id\' is not a valid build id.'=>'Поље „server_build_id“ у expected_manifest није важећи ИД изградње.','failed to parse _manifest.json: %s'=>'није успело рашчлањивање датотеке _manifest.json: %s','it would orphan %1$d of %2$d managed components (more than half)'=>'створило би сирочад од %1$d од %2$d управљаних компоненти (више од половине)','it would orphan every managed %1$s component (%2$d of %2$d)'=>'створило би сирочад од свих управљаних компоненти врсте %1$s (%2$d од %2$d)','l10n.php entry count mismatch for %s'=>'Број уноса у l10n.php датотеци не одговара за %s','manifest.json has an invalid \'default_domain_entries\'.'=>'manifest.json има неважеће поље „default_domain_entries“.','manifest.json has an invalid \'default_domain_files\'.'=>'manifest.json има неважеће поље „default_domain_files“.','manifest.json in the zip is not valid JSON.'=>'manifest.json у zip-у није исправан JSON.','manifest.json is missing or has an invalid \'%s\'.'=>'manifest.json недостаје или има неважеће поље „%s“.','manifest.json is missing or has an invalid \'build_no\'.'=>'manifest.json недостаје или има неважеће поље „build_no“.','manifest.json is missing or has an invalid \'entries\'.'=>'manifest.json недостаје или има неважеће поље „entries“.','manifest.json is missing or has an invalid \'extra_domains\'.'=>'manifest.json недостаје или има неважеће поље „extra_domains“.','manifest.json is missing or has an invalid \'files\'.'=>'manifest.json недостаје или има неважеће поље „files“.','manifest.json\'s \'%s\' does not match the expected value.'=>'Поље „%s“ у датотеци manifest.json не одговара очекиваној вредности.','manifest.json\'s \'contract\' is not a valid version string.'=>'Поље „contract“ у датотеци manifest.json није важећи низ верзије.','manifest.json\'s \'kind\' must be \'plugin\' or \'theme\'.'=>'Поље „kind“ у датотеци manifest.json мора бити „plugin“ или „theme“.','manifest.json\'s \'server_build_id\' is not a valid build id.'=>'Поље „server_build_id“ у датотеци manifest.json није важећи ИД изградње.','manifest.json\'s \'status\' must be \'published\'.'=>'Поље „status“ у датотеци manifest.json мора бити „published“.','nonce must be a hexadecimal string.'=>'nonce мора бити хексадецимални низ.','per day'=>'дневно','rc_…'=>'rc_…','sha256 mismatch for %s'=>'Неусклађеност sha256 суме за %s','sha256 mismatch for default/%s'=>'Неусклађеност sha256 суме за default/%s','component kind in the sweep brake messageplugin'=>'додатак','component kind in the sweep brake messagetheme'=>'тема','problem report categoryOther'=>'Остало','translation statusAvailable'=>'Доступно','translation statusInstalled'=>'Инсталирано']];